from taf.ul.kpi_selector.operations.factory_prototype.classical_factory_prototype import OperationFactoryPrototype
from taf.ul.kpi_selector.operations.sw_update.classical_sw_update.sw_update_22R1 import SwUpdate22R1
from taf.ul.kpi_selector.operations.sw_update.classical_sw_update.sw_update_24R1 import SwUpdate24R1


class SwUpdateFactory(OperationFactoryPrototype):
    def __init__(self):
        super(SwUpdateFactory, self).__init__()

    def get_kpi(self, inter_release=False):
        """
        Gets kpi for software update operation.
        :param inter_release: boolean value whether activated sw is of different stream than the one active on BTS;
                              defaults to False
        :type inter_release: bool
        :return: dictionary with timeout, requirement and operation description for software update
        :rtype: dict
        """

        if "SBTS22R1" <= self.bts.stream < "SBTS24R1":
            return SwUpdate22R1(self.bts).get_kpi(inter_release=inter_release)

        elif self.bts.stream >= "SBTS24R1":
            return SwUpdate24R1(self.bts).get_kpi(inter_release=inter_release)
